import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`workout-builder`,heroTitle:`Build your perfect workout in minutes`,heroSubtitle:`Perplexity Computer researches your fitness profile, designs periodized programs, and generates ready-to-follow workout plans — automatically.`,inputUrlCta:`Build my program`,inputUrlPlaceholder:`e.g. bodybuilding.com`,inputUrlPrefill:`Go to {url} and analyze the fitness content, training philosophy, exercise library, and any athlete or client profiles available. Then build me a comprehensive, personalized workout program. 1) Identify the training style, equipment available, and target audience from the site. 2) Design a 4-week periodized workout program with progressive overload — including warm-ups, main lifts, accessory work, and cooldowns for each session. 3) Structure the program for 4-5 training days per week with clearly defined muscle group splits or movement patterns. 4) For each exercise, include sets, reps, tempo, rest periods, and RPE targets. 5) Add a weekly progression scheme showing how to increase volume or intensity each week. 6) Include exercise substitutions for home gym and commercial gym setups. 7) Generate a printable workout log and a summary dashboard showing weekly volume per muscle group.`,heroOverlaySteps:[`Analyzing training style, equipment, and fitness philosophy`,`Designing a periodized program with progressive overload`,`Building detailed sessions with sets, reps, tempo, and rest periods`,`Your full workout program with tracking logs — ready to train`],generatingSteps:[`Visiting {url} to extract training style, exercises, and programming cues`,`Designing an agent to build a periodized workout plan with progressive overload`,`Configuring session splits, exercise selections, and weekly progression schemes`,`Setting up your printable workout log and volume tracking dashboard`],featureSectionTitle:`From fitness goals to full training program`,featureCardTitles:[`Connects to your fitness stack`,`Outputs you can follow`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Drive, Notion, Canva — Computer exports your workout programs, tracking logs, and visual guides straight into the tools you already use.`,`Periodized training splits. Daily session breakdowns with sets, reps, and rest. Progressive overload schedules. Printable workout logs. Weekly volume summaries by muscle group.`],capabilitySectionTitle:`Your personal trainer, on autopilot`,capabilitySectionSubtitle:`Share your goals, step away, come back to a complete training program.`,capabilityCards:[{title:`Program Design`,description:`Computer can build multi-week periodized programs — with intelligent splits, progressive overload, and deload weeks built in.`},{title:`Exercise Selection`,description:`Computer can pick exercises matched to your equipment, experience level, and goals — with substitutions for every movement.`},{title:`Volume Tracking`,description:`Computer can calculate weekly volume per muscle group and flag imbalances — so your program hits every area effectively.`},{title:`Connect Your Tools`,description:`Computer can push workout plans to Google Sheets, Notion, and Google Drive — build workflows across your entire fitness and productivity stack.`},{title:`Remember & Adapt`,description:`Computer can remember your training history, PRs, and preferences across sessions — so every new program builds on your progress.`},{title:`Monitor & Update`,description:`Computer can check your progression targets weekly and adjust volume, intensity, or exercise selection when you plateau or need a deload.`}]});export{t as default};
